CREATE OR REPLACE PROCEDURE bulk_test_pkg_archive_old_orders () AS $body$
DECLARE

    TYPE t_id_tab IS TABLE OF orders.order_id%TYPE;
    v_ids t_id_tab;

BEGIN
    SELECT order_id
    BULK COLLECT INTO STRICT v_ids
    FROM orders
    WHERE status = 'CLOSED';

    FORALL i IN 1 .. v_ids.COUNT
      DELETE FROM orders WHERE order_id = v_ids(i);

    COMMIT;
  END;
$body$
LANGUAGE PLPGSQL
